INSERT INTO public.questions (id, code, text, answer_group_id, question_order, is_active, survey_id) VALUES
  (3000, 'CL_P13', 'Qual a sua religião?', NULL, 13, true, 3),
  (3001, 'CL_P14', 'Com que frequência o(a) Sr(a) vai à missa ou culto religioso?', 210, 14, true, 3),
  (3002, 'CL_P15', 'As lideranças da sua Igreja apoiaram algum dos seguintes candidatos nas eleições de 2022?', 211, 15, true, 3),
  (3003, 'CL_P16', 'Existe algum partido político que representa a maneira como o(a) Sr(a) pensa?', 212, 16, true, 3),
  (3004, 'CL_P17', 'Qual partido melhor representa a maneira como o(a) Sr(a) pensa?', 213, 17, true, 3),
  (3005, 'CL_P18', 'Agora o(a) Sr(a) poderia informar o quanto gosta ou não gosta dos partidos políticos a seguir? Com base numa escala que vai de 0 a 10, na qual 0 significa "não gosto de jeito nenhum" e 10 significa "gosto muito". Quando eu falar o nome de um partido que o(a) Sr(a) não conhece, apenas diga que não conhece. Vamos lá: de 0 a 10, o quanto o(a) Sr(a) gosta do(a) .........? PT', 200, 18, true, 3),
  (3006, 'CL_P19', 'Agora o(a) Sr(a) poderia informar o quanto gosta ou não gosta dos partidos políticos a seguir? Com base numa escala que vai de 0 a 10, na qual 0 significa "não gosto de jeito nenhum" e 10 significa "gosto muito". Quando eu falar o nome de um partido que o(a) Sr(a) não conhece, apenas diga que não conhece. Vamos lá: de 0 a 10, o quanto o(a) Sr(a) gosta do(a) .........? MDB', 200, 19, true, 3),
  (3007, 'CL_P20', 'Agora o(a) Sr(a) poderia informar o quanto gosta ou não gosta dos partidos políticos a seguir? Com base numa escala que vai de 0 a 10, na qual 0 significa "não gosto de jeito nenhum" e 10 significa "gosto muito". Quando eu falar o nome de um partido que o(a) Sr(a) não conhece, apenas diga que não conhece. Vamos lá: de 0 a 10, o quanto o(a) Sr(a) gosta do(a) .........? PL / Partido do Bolsonaro', 200, 20, true, 3),
  (3008, 'CL_P21', 'Agora o(a) Sr(a) poderia informar o quanto gosta ou não gosta dos partidos políticos a seguir? Com base numa escala que vai de 0 a 10, na qual 0 significa "não gosto de jeito nenhum" e 10 significa "gosto muito". Quando eu falar o nome de um partido que o(a) Sr(a) não conhece, apenas diga que não conhece. Vamos lá: de 0 a 10, o quanto o(a) Sr(a) gosta do(a) .........? Partidos do Centrão', 200, 21, true, 3),
  (3009, 'CL_P22', 'Com base em uma escala que vai de 0 a 10, sendo 0 "desaprova totalmente" e 10 "aprova totalmente", até que ponto o(a) Sr(a) aprova o direito do (LER O NOME DO PARTIDO) de concorrer nas eleições para presidente do Brasil? PT', 201, 22, true, 3),
  (3010, 'CL_P23', 'Com base em uma escala que vai de 0 a 10, sendo 0 "desaprova totalmente" e 10 "aprova totalmente", até que ponto o(a) Sr(a) aprova o direito do (LER O NOME DO PARTIDO) de concorrer nas eleições para presidente do Brasil? MDB', 201, 23, true, 3),
  (3011, 'CL_P24', 'Com base em uma escala que vai de 0 a 10, sendo 0 "desaprova totalmente" e 10 "aprova totalmente", até que ponto o(a) Sr(a) aprova o direito do (LER O NOME DO PARTIDO) de concorrer nas eleições para presidente do Brasil? PL / Partido do Bolsonaro', 201, 24, true, 3),
  (3012, 'CL_P25', 'Com base em uma escala que vai de 0 a 10, sendo 0 "desaprova totalmente" e 10 "aprova totalmente", até que ponto o(a) Sr(a) aprova o direito do (LER O NOME DO PARTIDO) de concorrer nas eleições para presidente do Brasil? Partidos do Centrão', 201, 25, true, 3),
  (3013, 'CL_P26', 'Existem ideias que algumas pessoas consideram ruins ou perigosas. Por exemplo, considere uma pessoa que acredita que os negros são inferiores aos brancos. Se essa pessoa quisesse fazer um discurso em sua comunidade defendendo que os negros são inferiores, ela deveria ter permissão para falar ou não?', 214, 26, true, 3),
  (3014, 'CL_P27', 'Agora considere uma pessoa que defende acabar com as eleições para que os militares governem o país. Se essa pessoa quisesse fazer um discurso em sua comunidade defendendo essa ideia, ela deveria ter permissão para falar ou não?', 214, 27, true, 3),
  (3015, 'CL_P28', 'E uma pessoa que defende o comunismo? Se essa pessoa quisesse fazer um discurso em sua comunidade defendendo essa ideia, ele(a) deveria ter permissão para falar ou não?', 214, 28, true, 3),
  (3016, 'CL_P29', 'E quanto a uma pessoa que defende que os cidadãos deveriam ter o direito de andar armados. Se essa pessoa quisesse fazer um discurso em sua comunidade defendendo essa ideia, ela deveria ter permissão para falar ou não?', 214, 29, true, 3),
  (3017, 'CL_P30', 'Agora imagine alguém que defende que as mulheres tenham o direito de escolher se querem ou não querem fazer um aborto. Se essa pessoa quisesse fazer um discurso em sua comunidade defendendo essa ideia, ela deveria ter permissão para falar ou não?', 214, 30, true, 3),
  (3018, 'CL_P31', 'Considere agora um petista/ simpatizante do PT. Caso essa pessoa queira fazer um discurso em sua comunidade defendendo suas ideias, ela deveria ter permissão para falar ou não?', 214, 31, true, 3),
  (3019, 'CL_P32', 'Agora um bolsonarista / simpatizante do Bolsonaro. Caso essa pessoa queira fazer um discurso em sua comunidade defendendo suas ideias, ela deveria ter permissão para falar ou não?', 214, 32, true, 3),
  (3020, 'CL_P33', 'Suponha que um filho seu ou filha sua fosse se casar. Por favor, indique o quanto ficaria satisfeito ou insatisfeito, considerando 0 como "muito insatisfeito" e 10 como "muito satisfeito", se ele ou ela se casasse com um ou uma Bolsonarista / Eleitor do Bolsonaro.', 202, 33, true, 3),
  (3021, 'CL_P34', 'E como o(a) Sr(a) se sentiria se ele ou ela se casasse com um Lulista / Eleitor(a) do Lula? Por favor, considere a mesma escala onde 0 significa "muito insatisfeito" e 10 "muito satisfeito".', 202, 34, true, 3),
  (3022, 'CL_P35', 'Na sua opinião, quem deve se responsabilizar mais para garantir o sustento das pessoas? Escolha entre as duas alternativas que vou ler: (LER ALTERNATIVAS DE 1 A 2) [LER ALTERNATIVAS EM RODÍZIO]', 215, 35, true, 3),
  (3023, 'CL_P36', 'O(A) Sr(a) poderia me dizer em que grau concorda ou discorda, em uma escala de 0 (discorda totalmente) a 10 (concorda totalmente), com as seguintes proposições totalmente) a 10 (concorda totalmente), com as seguintes proposições O Estado brasileiro, em vez do setor privado, deveria ser dono das empresas e indústrias mais importantes do país.', 203, 36, true, 3),
  (3024, 'CL_P37', 'O(A) Sr(a) poderia me dizer em que grau concorda ou discorda, em uma escala de 0 (discorda totalmente) a 10 (concorda totalmente), com as seguintes proposições totalmente) a 10 (concorda totalmente), com as seguintes proposições O Estado brasileiro deve implementar políticas firmes para reduzir a desigualdade de renda entre ricos e pobres', 203, 37, true, 3),
  (3025, 'CL_P38', 'O(A) Sr(a) poderia me dizer em que grau concorda ou discorda, em uma escala de 0 (discorda totalmente) a 10 (concorda totalmente), com as seguintes proposições totalmente) a 10 (concorda totalmente), com as seguintes proposições A proteção do meio ambiente deveria ser prioritária, mesmo se desacelerasse o desenvolvimento econômico e diminuísse a oferta de empregos', 203, 38, true, 3),
  (3026, 'CL_P39', 'O(A) Sr(a) poderia me dizer em que grau concorda ou discorda, em uma escala de 0 (discorda totalmente) a 10 (concorda totalmente), com as seguintes proposições totalmente) a 10 (concorda totalmente), com as seguintes proposições Desenvolvimento econômico e criação de empregos deveriam ser prioritários, mesmo que o meio ambiente sofra algum dano.', 203, 39, true, 3),
  (3027, 'CL_P40', 'Agora vou enumerar uma série de temas debatidos na sociedade brasileira. O(A) Sr(a) poderia me dizer em que grau concorda ou discorda, em uma escala de 0 (discorda totalmente) a 10 (concorda totalmente), com as seguintes proposições Casamento civil de pessoas do mesmo sexo', 203, 40, true, 3),
  (3028, 'CL_P41', 'Agora vou enumerar uma série de temas debatidos na sociedade brasileira. O(A) Sr(a) poderia me dizer em que grau concorda ou discorda, em uma escala de 0 (discorda totalmente) a 10 (concorda totalmente), com as seguintes proposições Redução da maioridade penal', 203, 41, true, 3),
  (3029, 'CL_P42', 'Agora vou enumerar uma série de temas debatidos na sociedade brasileira. O(A) Sr(a) poderia me dizer em que grau concorda ou discorda, em uma escala de 0 (discorda totalmente) a 10 (concorda totalmente), com as seguintes proposições A pena de morte', 203, 42, true, 3),
  (3030, 'CL_P43', 'Agora vou enumerar uma série de temas debatidos na sociedade brasileira. O(A) Sr(a) poderia me dizer em que grau concorda ou discorda, em uma escala de 0 (discorda totalmente) a 10 (concorda totalmente), com as seguintes proposições Liberação do uso de drogas', 203, 43, true, 3),
  (3031, 'CL_P44', 'Agora vou enumerar uma série de temas debatidos na sociedade brasileira. O(A) Sr(a) poderia me dizer em que grau concorda ou discorda, em uma escala de 0 (discorda totalmente) a 10 (concorda totalmente), com as seguintes proposições A proibição de venda de armas de fogo', 203, 44, true, 3),
  (3032, 'CL_P45', 'Agora vou enumerar uma série de temas debatidos na sociedade brasileira. O(A) Sr(a) poderia me dizer em que grau concorda ou discorda, em uma escala de 0 (discorda totalmente) a 10 (concorda totalmente), com as seguintes proposições Adoção de cotas raciais nas universidades', 203, 45, true, 3),
  (3033, 'CL_P46', 'Agora vou enumerar uma série de temas debatidos na sociedade brasileira. O(A) Sr(a) poderia me dizer em que grau concorda ou discorda, em uma escala de 0 (discorda totalmente) a 10 (concorda totalmente), com as seguintes proposições Permissão para mineração nas terras indígenas', 203, 46, true, 3),
  (3034, 'CL_P47', 'Agora vou enumerar uma série de temas debatidos na sociedade brasileira. O(A) Sr(a) poderia me dizer em que grau concorda ou discorda, em uma escala de 0 (discorda totalmente) a 10 (concorda totalmente), com as seguintes proposições A decisão sobre fazer ou não um aborto deve ser tomado exclusivamente pela mulher.', 203, 47, true, 3),
  (3035, 'CL_P48', 'Agora vou enumerar uma série de temas debatidos na sociedade brasileira. O(A) Sr(a) poderia me dizer em que grau concorda ou discorda, em uma escala de 0 (discorda totalmente) a 10 (concorda totalmente), com as seguintes proposições Para reduzir os homicídios é preciso prevenção, com oportunidades de educação e trabalho', 203, 48, true, 3),
  (3036, 'CL_P49', 'Agora vou enumerar uma série de temas debatidos na sociedade brasileira. O(A) Sr(a) poderia me dizer em que grau concorda ou discorda, em uma escala de 0 (discorda totalmente) a 10 (concorda totalmente), com as seguintes proposições Para reduzir os homicídios é preciso prevenção, com oportunidades de educação e trabalho', 203, 49, true, 3),
  (3037, 'CL_P50', 'Com qual das seguintes três frases o(a) Sr(a) está mais de acordo', 216, 50, true, 3),
  (3038, 'CL_P51', 'Com base em uma escala que vai de 0 a 10, onde 0 significa "nada justificável" e 10 "totalmente justificável", o quanto o(a) Sr(a) acredita que quando o país está enfrentando dificuldades é justificável que o presidente da República feche o Congresso e governe sem o Congresso?', 204, 51, true, 3),
  (3039, 'CL_P52', 'Existem pessoas que dizem que precisamos de um líder forte, que não seja eleito através do voto. Outros dizem que, ainda que as coisas não funcionem, a democracia eleitoral, ou seja, voto popular, é sempre o melhor. Em uma escala de 0 a 10, onde 0 é "concordo fortemente que necessitamos de um líder forte que não seja eleito através do voto" e 10 é "concordo fortemente que a democracia eleitoral é o melhor", em que ponto da escala o(a) Sr(a) se posiciona?', 205, 52, true, 3),
  (3040, 'CL_P53', 'Em uma escala que vai de 0 a 10, onde 0 significa "desaprova fortemente" e 10 "aprova fortemente", até que ponto o(a) Sr(a) aprova a participação de pessoas em manifestações permitidas por lei?', 206, 53, true, 3),
  (3041, 'CL_P54', 'Para poder prender criminosos, algumas pessoas acreditam que as autoridades devem sempre respeitar as leis, enquanto outras acreditam que, em certas ocasiões, as autoridades podem agir sem respeitar a lei. Em uma escala que vai de 0 a 10, onde 0 significa "concordo totalmente que, para poder prender criminosos, autoridades podem agir sem respeitar a lei" e 10 "concordo totalmente que, para poder prender criminosos, elas devem sempre respeitar as leis", em que ponto da escala o(a) Sr(a) se posiciona?', 207, 54, true, 3),
  (3042, 'CL_P55', 'Em uma escala que vai de 0 a 10, onde 0 significa "discorda totalmente" e 10 "concorda totalmente", até que ponto o(a) Sr(a) concorda que a vontade da maioria deveria sempre prevalecer, mesmo que prejudique os direitos das minorias?', 208, 55, true, 3),
  (3043, 'CL_P56', 'Em muitos países, os resultados das eleições têm sido questionados pelos candidatos derrotados. No dia 8 de janeiro, em Brasília, um grupo de pessoas invadiu os prédios dos três poderes em protesto contra o resultado das eleições e pedindo a intervenção militar. Em relação a manifestações como essa, o(a) Sr(a):', 217, 56, true, 3),
  (3044, 'CL_P57', 'O quanto o(a) Sr(a) se interessa por política? O(a) Sr(a) diria que é', 218, 57, true, 3),
  (3045, 'CL_P58_A1', 'Por favor, considere uma escala de 0 a 10, onde 0 significa "não se justificaria" e 10 significa "se justificaria". Algumas pessoas dizem que em certas circunstâncias se justificaria um golpe militar. Na sua opinião, se justificaria um golpe militar diante de casos como o resultado das eleições presidenciais de 2022?', 209, 58, true, 3),
  (3046, 'CL_P58_A2', 'Por favor, considere uma escala de 0 a 10, onde 0 significa "não se justificaria" e 10 significa "se justificaria". Algumas pessoas dizem que em certas circunstâncias se justificaria uma intervenção militar. Na sua opinião, se justificaria uma intervenção militar diante de casos como o resultado das eleições presidenciais de 2022?', 209, 59, true, 3),
  (3047, 'CL_P59_A1', 'Agora vamos conversar sobre eleições para deputado federal. Vou apresentar algumas informações sobre um hipotético candidato a deputado do seu estado e vou pedir que o(a) Sr(a) me diga a sua opinião sobre ele. O deputado Jose da Silva tem 45 anos e se formou em Pedagogia. No seu primeiro mandato, atuou principalmente em favor da educação infantil. Ele quer se reeleger para continuar esse trabalho. Sabendo disso, o(a) Sr(a):', 219, 60, true, 3),
  (3048, 'CL_P59_A2', 'Agora vamos conversar sobre eleições para deputado federal. Vou apresentar algumas informações sobre um hipotético candidato a deputado do seu estado e vou pedir que o(a) Sr(a) me diga a sua opinião sobre ele. O deputado Jose da Silva tem 45 anos, se formou em Pedagogia e é pastor evangélico. No seu primeiro mandato atuou principalmente em favor da educação infantil. Ele quer se reeleger para continuar esse trabalho. Sabendo disso, o(a) Sr(a):', 219, 61, true, 3),
  (3049, 'CL_P60', 'Em qual destas faixas que vou citar está a renda total da sua família no mês passado, somando o salário de todas as pessoas que moram com o(a) Sr(a), inclusive o seu?', 220, 62, true, 3),
  (3050, 'CL_P61', 'O(a) Sr(a) votou no primeiro turno nesta eleição para presidente?', 221, 63, true, 3),
  (3051, 'CL_P62', 'Em qual dos candidatos cujo nome eu vou ler o(a) Sr(a) votou no primeiro turno para presidente?', 222, 64, true, 3),
  (3052, 'CL_P63', 'O(a) Sr(a) votou no segundo turno nesta eleição para presidente?', 223, 65, true, 3),
  (3053, 'CL_P64', 'Em quem o(a) Sr(a) votou no segundo turno para presidente?', 224, 66, true, 3),
  (3054, 'CL_P65', 'O(a) Sr(a) considera que a situação econômica atual do país está melhor, igual ou pior que há doze meses?', 225, 67, true, 3);
